(function sitePrices(){
  'use strict';const fmt=x=>Number(x).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2});let next=Date.now()+300000,payload=null;
  document.body.dataset.prices='loading';
  const top=document.getElementById('silver-rate-bar');if(top)top.innerHTML='<span class="rate-label">Kurs srebra</span><strong>— zł/g</strong><span class="rate-time">Pobieranie danych…</span>';
  document.querySelectorAll('[data-home-purity]').forEach(e=>e.textContent='—');
  const rows=document.getElementById('price-rows');if(rows)rows.replaceChildren();
  const basePlaceholder=document.getElementById('base-price');if(basePlaceholder)basePlaceholder.textContent='—';
  const priceTabs=document.querySelector('.price-category-tabs');let selected='jewellery';
  function renderProducts(){if(!priceTabs||!payload)return;const target=document.getElementById('product-prices'),pricing=document.querySelector('.pricing-layout'),base=pricing?.querySelector('.table-wrap:not(.product-table)');if(selected==='jewellery'){if(pricing)pricing.hidden=false;if(base)base.hidden=false;target.replaceChildren();return;}const desktop=matchMedia('(min-width:801px)').matches;if(pricing)pricing.hidden=!desktop;if(base)base.hidden=desktop;if(desktop)pricing.append(target);else priceTabs.parentElement.append(target);const data=window.silverLiveProducts[selected]||[];const table=document.createElement('table');table.innerHTML='<thead><tr><th>Produkt</th><th>Próba</th><th>Gramatura</th><th>Cena</th></tr></thead>';const body=document.createElement('tbody');for(const item of data){const row=document.createElement('tr');const name=document.createElement('td'),b=document.createElement('b'),small=document.createElement('small');b.textContent=item.name;small.className='product-mobile-details';const purity=Number(item.purity)>=999?'999,9':String(item.purity).replace('.',',');small.textContent='pr. '+purity+' · '+String(item.grossWeight).replace('.',',')+' g';name.append(b,small);row.append(name);for(const text of [purity,item.grossWeight+' g',fmt(item.price)+' zł']){const td=document.createElement('td');td.textContent=text;row.append(td);}body.append(row);}table.append(body);const wrap=document.createElement('div');wrap.className='table-wrap product-table';wrap.append(table);target.replaceChildren(wrap);}
  priceTabs?.querySelectorAll('[data-price-kind]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.priceKind;priceTabs.querySelectorAll('button').forEach(e=>e.setAttribute('aria-selected',String(e===b)));renderProducts();}));
  if(priceTabs)matchMedia('(min-width:801px)').addEventListener('change',renderProducts);
  function apply(data){const silver=data?.metals?.silver;if(!silver||!Number.isFinite(Number(silver.spot))||!silver.purities)throw Error('Brak danych cen');payload=data;window.silverPricePayload=data;window.silverLivePrices=Object.fromEntries(Object.entries(silver.purities).map(([p,item])=>[p,Number(item.price)]));window.silverLiveProducts={coins:data.products?.silverCoins||[],bars:data.products?.silverBars||[]};window.silverMarket={spot:Number(silver.spot),change:Number(silver.change),fetchedAt:data.fetchedAt};const up=Number(silver.change)>=0;const time=new Intl.DateTimeFormat('pl-PL',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(data.fetchedAt));if(top)top.innerHTML='<span class="rate-label">Kurs srebra</span><strong>'+fmt(silver.spot)+' zł/g</strong><span class="rate-change '+(up?'up':'down')+'">'+(up?'▲':'▼')+' '+fmt(Math.abs(silver.change))+'%</span><span class="rate-time">aktualizacja: '+time+'</span>';document.querySelectorAll('[data-home-purity]').forEach(e=>{const p=window.silverLivePrices[e.dataset.homePurity];e.textContent=Number.isFinite(p)?fmt(p)+' zł/g':'—';});const badge=document.querySelector('[data-home-change]');if(badge){badge.className='home-rate-change '+(up?'up':'down');badge.textContent=(up?'▲':'▼')+' '+fmt(Math.abs(silver.change))+'%';}const base=document.getElementById('base-price');if(base)base.textContent=fmt(window.silverLivePrices[999])+' zł / g';if(rows){rows.replaceChildren();for(const [purity,price]of Object.entries(window.silverLivePrices).sort(([a],[b])=>a-b)){const tr=document.createElement('tr');tr.innerHTML='<td><b>'+purity+'</b></td><td>'+fmt(price)+' zł</td><td><a class="text-button" href="/wycena.html" data-live-price="'+purity+'">Wyceń</a></td>';tr.querySelector('a').addEventListener('click',()=>{try{sessionStorage.setItem('silver-intent',JSON.stringify({kind:'scrap',purity:Number(purity)}));}catch{}});rows.append(tr);}}renderProducts();document.body.dataset.prices='live';document.dispatchEvent(new CustomEvent('silver-prices-ready',{detail:data}));}
  async function load(){next=Date.now()+300000;try{const r=await fetch('/ceny-live.php?site=silver',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);apply(await r.json());}catch{document.body.dataset.prices=payload?'cached':'unavailable';if(top&&!payload)top.innerHTML='<span class="rate-label">Kurs srebra</span><strong>Chwilowo niedostępny</strong>';else if(top){const time=top.querySelector('.rate-time');if(time)time.textContent='ostatnie pobrane dane';}}}
  function tick(){const sec=Math.max(0,Math.ceil((next-Date.now())/1000)),label=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');document.querySelectorAll('[data-home-countdown]').forEach(e=>e.textContent=label);document.querySelectorAll('.quote-timer').forEach(e=>e.textContent='Następne notowanie za '+label);}
  load();setInterval(load,300000);tick();setInterval(tick,1000);
})();

